import{_ as s,o as t,c as n,a2 as r}from"./chunks/framework.LX5S0jbT.js";const u=JSON.parse('{"title":"How Pi Works","description":"","frontmatter":{},"headers":[],"relativePath":"how-pi-works.md","filePath":"how-pi-works.md"}'),o={name:"how-pi-works.md"};function a(i,e,d,c,l,h){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="how-pi-works" tabindex="-1">How Pi Works <a class="header-anchor" href="#how-pi-works" aria-label="Permalink to &quot;How Pi Works&quot;">​</a></h1><p>Pi coordinates model requests, tool execution, context assembly, and session storage. A session is Pi&#39;s record of a conversation, including messages, tool calls and results, model changes, compactions, and other events.</p><p>Messages and events in a session form a tree. Each path through that tree is a branch. The branch ending at the current entry is the active branch and supplies the history for the next model request.</p><h2 id="agent-loop" tabindex="-1">Agent loop <a class="header-anchor" href="#agent-loop" aria-label="Permalink to &quot;Agent loop&quot;">​</a></h2><p>A submitted message is added to the active branch. Pi builds a model request from the system prompt, active branch, available tools, and model settings, then sends it through the selected provider.</p><p>The provider streams an assistant response, which can contain text and tool calls. Pi records the response, executes each tool call, and records the results. That completes one turn. If tool results or queued messages require another model request, Pi starts another turn. Otherwise, the run ends.</p><p>Steering messages enter after the current assistant turn. Follow-up messages enter after the agent has finished its pending work. Aborting stops the current run and returns queued messages to the editor.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The active branch supplies conversation history. Pi converts its session entries into model-compatible user, assistant, and tool-result messages.</p><p>Pi builds the system prompt from its base instructions and discovered context files. The request also carries tool definitions and skill descriptions.</p><p>Full skill instructions are loaded on demand. Extensions can add instructions or transform context.</p><p>Prompt templates expand editor input before it becomes a user message. Selected files, images, pasted text, and shell output can become message content.</p><h2 id="sessions" tabindex="-1">Sessions <a class="header-anchor" href="#sessions" aria-label="Permalink to &quot;Sessions&quot;">​</a></h2><p>Persistent sessions are JSONL files. Each tree entry has an ID and refers to its parent. The current entry identifies the active branch.</p><p>Continuing from an earlier entry creates another branch in the same file. Forking and cloning copy selected history into a new session file.</p><p>Model context is reconstructed from the active branch. Compaction inserts a summary entry that replaces older messages in subsequent model requests. The original entries remain in the session tree.</p><h2 id="interfaces" tabindex="-1">Interfaces <a class="header-anchor" href="#interfaces" aria-label="Permalink to &quot;Interfaces&quot;">​</a></h2><p>Interactive mode renders session and agent events in the terminal. Print mode runs a prompt and writes the final response. JSON mode writes agent events as JSONL.</p><p>RPC mode accepts JSONL commands on stdin and writes responses and events to stdout. The TypeScript SDK creates and controls agent sessions in process.</p><p>All interfaces use the same agent and session mechanisms.</p><h2 id="extensions-and-resources" tabindex="-1">Extensions and resources <a class="header-anchor" href="#extensions-and-resources" aria-label="Permalink to &quot;Extensions and resources&quot;">​</a></h2><p>Extensions are TypeScript modules loaded into the Pi process. Their factory functions register tools, commands, shortcuts, providers, event handlers, renderers, and terminal UI.</p><p>Skills provide on-demand instructions and supporting files. Prompt templates provide reusable message text. Themes provide terminal colors. Pi packages distribute these resources through npm or git.</p><h2 id="trust-and-permissions" tabindex="-1">Trust and permissions <a class="header-anchor" href="#trust-and-permissions" aria-label="Permalink to &quot;Trust and permissions&quot;">​</a></h2><p>Pi resolves project trust before loading project settings and resources. After the trust decision and project-resource loading, Pi loads context files. Enabled tools use the operating-system permissions of the Pi process. Extensions execute inside that process.</p>',25)])])}const m=s(o,[["render",a]]);export{u as __pageData,m as default};
